# is_perfect_square :: (16,)
def is_perfect_square(n):
    if n < 0:
        return False
    r = int(n ** 0.5)
    return r * r == n or (r + 1) * (r + 1) == n

if __name__ == '__main__':
    print(is_perfect_square((16,)))

